styles:
/* ===== Careers job-posting page (scoped) ===== */
.page-career .career-hero { max-width: 900px; }
.page-career .career-hero__title {
  font-family: var(--font-display);
  font-size: clamp(40px, 6.6vw, 92px);
  line-height: 1.06; color: var(--grey-700); letter-spacing: -0.01em;
  margin-bottom: clamp(20px, 3vw, 30px);
}
.page-career .career-meta {
  display: flex; flex-wrap: wrap; gap: clamp(18px, 3vw, 40px);
  margin-top: 6px;
}
.page-career .career-meta__item { display: flex; flex-direction: column; gap: 4px; }
.page-career .career-meta__label {
  font-size: 13px; letter-spacing: .12em; text-transform: uppercase;
  color: var(--grey-500);
}
.page-career .career-meta__value {
  font-family: var(--font-display); font-size: clamp(17px, 1.4vw, 21px);
  color: var(--grey-900);
}

.page-career .career-figure {
  border-radius: var(--radius-lg); overflow: hidden; background: var(--bg-alt);
  aspect-ratio: 16 / 8;
}
.page-career .career-figure img { width: 100%; height: 100%; object-fit: cover; }

/* readable single-column measure */
.page-career .career-body { max-width: 760px; margin-inline: auto; }
.page-career .career-block { margin-bottom: clamp(38px, 5vw, 64px); }
.page-career .career-block:last-child { margin-bottom: 0; }
.page-career .career-block h2 {
  font-family: var(--font-display); font-size: clamp(28px, 3.4vw, 46px);
  color: var(--grey-900); line-height: 1.08; margin-bottom: clamp(16px, 2vw, 24px);
}
.page-career .career-block .lead {
  font-family: var(--font-display); color: var(--red);
  font-size: clamp(20px, 2vw, 28px); line-height: 1.25; margin-bottom: 18px;
}
.page-career .career-block p {
  color: var(--grey-700); font-size: clamp(16px, 1.15vw, 19px);
  line-height: 1.75; margin-bottom: 16px;
}
.page-career .career-block p:last-child { margin-bottom: 0; }
.page-career .career-list {
  display: flex; flex-direction: column; gap: 14px; margin-top: 6px;
}
.page-career .career-list li {
  position: relative; padding-left: 30px;
  color: var(--grey-700); font-size: clamp(16px, 1.1vw, 18px); line-height: 1.6;
}
.page-career .career-list li::before {
  content: ""; position: absolute; left: 0; top: .55em;
  width: 14px; height: 2px; background: var(--red);
}

.page-career .career-apply {
  border-top: 1px solid var(--line); padding-top: clamp(34px, 4vw, 54px);
}
.page-career .apply-btn {
  display: inline-flex; align-items: center; gap: 14px; margin-top: 26px;
  background: var(--red); color: #fff; border-radius: 999px;
  padding: 14px 16px 14px 28px; font-size: 18px;
  transition: transform .3s var(--ease);
}
.page-career .apply-btn .arrow {
  width: 36px; height: 36px; border-radius: 50%; background: #fff; color: var(--red);
  display: grid; place-items: center;
}
.page-career .apply-btn:hover { transform: translateY(-3px); }

.page-career .back-roles {
  display: inline-flex; align-items: center; gap: 10px;
  color: var(--grey-700); font-size: 16px; margin-bottom: clamp(28px, 4vw, 44px);
  transition: color .25s var(--ease);
}
.page-career .back-roles:hover { color: var(--red); }
.page-career .back-roles .arrow {
  width: 30px; height: 30px; border-radius: 50%; border: 1.5px solid var(--grey-300);
  display: grid; place-items: center; transition: border-color .3s, color .3s;
}
.page-career .back-roles:hover .arrow { border-color: var(--red); color: var(--red); }

.page-career .career-foot-link {
  text-align: center; padding-top: clamp(30px, 4vw, 48px);
}
.page-career .career-foot-link a {
  display: inline-flex; align-items: center; gap: 10px;
  color: var(--red); font-size: 17px;
}
